.article-shell .article > .event > time{
  display:inline-block!important;
  height:auto!important;
  max-width:100%!important;
  white-space:normal!important;
}

/* NK_AD_BLANK_VISUAL_GUARD_20260912
   Pokud reklama nema skutecny obrazek, nevyrabime dekorativni gradient ani obri prazdnou plochu. */
html body .article-shell[data-article-template="unified-v1"] .featured-cleaning-ad a.promo-card-wide.promo-card-full-image:not(:has(.promo-banner img))::before,
html body .article-shell[data-article-template="unified-v1"] .featured-rotating-ad a.promo-card-wide.promo-card-full-image:not(:has(.promo-banner img))::before,
html body .article-shell[data-article-template="unified-v1"] > .article a.promo-card-wide.promo-card-full-image:not(:has(.promo-banner img))::before,
html body a.promo-card-wide:not(:has(.promo-banner img))::before,
html body a.promo-card:not(:has(.promo-banner img))::before,
html body a.article-rail-card.is-image-error::before,
html body a.article-rail-card:not(:has(img))::before{
  content:none!important;
  display:none!important;
  width:0!important;
  height:0!important;
  min-height:0!important;
  margin:0!important;
  background:none!important;
  box-shadow:none!important;
}
html body a.promo-card-wide:not(:has(.promo-banner img)){
  height:auto!important;
  min-height:0!important;
  aspect-ratio:auto!important;
  overflow:hidden!important;
}
html body a.promo-card-wide:not(:has(.promo-banner img)) > .promo-banner-fallback{
  display:none!important;
  height:0!important;
  min-height:0!important;
  margin:0!important;
  padding:0!important;
}
html body a.promo-card-wide:not(:has(.promo-banner img)) > .promo-wide-copy{
  display:flex!important;
  position:static!important;
  flex-direction:column!important;
  gap:7px!important;
  min-height:0!important;
  padding:18px 24px 22px!important;
  background:#fff!important;
  color:#17242d!important;
}
html body a.article-rail-card.is-image-error .article-rail-fallback{display:none!important}
html body a.article-rail-card.is-image-error .article-rail-copy{display:flex!important}
